package interium.fabric;
import net.minecraft.client.MinecraftClient;import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gl.RenderPipelines;import net.minecraft.util.Identifier;import org.lwjgl.glfw.*;import org.lwjgl.system.*;import javax.imageio.ImageIO;import java.nio.ByteBuffer;
final class InteriumLogo {
 private static final Identifier IMAGE=Identifier.of("interium","textures/logo.png");private static boolean attempted;
 static void draw(DrawContext c,int x,int y,int size,float alpha){c.drawTexture(RenderPipelines.GUI_TEXTURED,IMAGE,x,y,0,0,size,size,64,64,64,64,Math.round(255*alpha)<<24|0xffffff);}
 static void window(MinecraftClient c){if(attempted)return;attempted=true;ByteBuffer pixels=null;try(var in=InteriumLogo.class.getResourceAsStream("/assets/interium/textures/logo.png");MemoryStack stack=MemoryStack.stackPush()){if(in==null)throw new IllegalStateException("Missing logo");var image=ImageIO.read(in);pixels=MemoryUtil.memAlloc(image.getWidth()*image.getHeight()*4);for(int y=0;y<image.getHeight();y++)for(int x=0;x<image.getWidth();x++){int p=image.getRGB(x,y);pixels.put((byte)(p>>16)).put((byte)(p>>8)).put((byte)p).put((byte)(p>>24));}pixels.flip();GLFWImage.Buffer icon=GLFWImage.malloc(1,stack);icon.width(image.getWidth()).height(image.getHeight()).pixels(pixels);GLFW.glfwSetWindowIcon(c.getWindow().getHandle(),icon);}catch(Exception e){System.err.println("Interium icon unavailable: "+e.getClass().getSimpleName());}finally{if(pixels!=null)MemoryUtil.memFree(pixels);}}
 static void smoke(){try(var in=InteriumLogo.class.getResourceAsStream("/assets/interium/textures/logo.png")){if(in==null)throw new AssertionError("Logo missing");var image=ImageIO.read(in);if(image.getWidth()!=64||image.getHeight()!=64)throw new AssertionError("Logo dimensions");System.out.println("INTERIUM_LOGO_RESOURCE_PASSED");}catch(java.io.IOException e){throw new AssertionError(e);}}
}
